            interval: '1d',
            key: 'BTCUSDT',
            open: 8690.5,
            high: 9000,
            low: 8110.04,
            close: 9899.05
          },
          {
            interval: '1d',
            key: 'BTCUSDT',
            open: 7755.66,
            high: athHigh,
            low: 7695.6,
            close
          }
        ];
      });
  };

  const mockLastBuyPrice = lastBuyPrice => {
